{
  "passageId": "surface-tension-laplace",
  "slots": [
    {
      "slot": 1,
      "stemPolarity": "SELECT_INCORRECT",
      "scope": "PASSAGE_WIDE",
      "concept": null,
      "answer": 3,
      "choices": [
        {
          "number": 1,
          "truth": "TRUE",
          "basis": [
            "구형은 동일한 부피에서 표면적이 최소인 형태인데 이는 액체 분자 간의 인력으로 발생하는 표면 장력의 작용 때문이다."
          ],
          "twist": null
        },
        {
          "number": 2,
          "truth": "TRUE",
          "basis": [
            "액체 방울에서 방울의 외부 압력과 표면 장력으로 인한 압력의 합이 내부 압력과 균형을 이룰 때 방울은 그 크기를 유지한다."
          ],
          "twist": null
        },
        {
          "number": 3,
          "truth": "FALSE",
          "basis": [
            "이 식에 따르면 액체 방울의 내부 압력과 외부 압력의 차이는 구형의 액체 방울에서 표면 장력에 정비례하고 액체 방울의 반지름에 반비례한다."
          ],
          "twist": {
            "label": "반비례 관계의 역전",
            "targetQuote": "액체 방울의 반지름에 반비례한다.",
            "change": "표면 장력이 일정한 구형 액체 방울에서 반지름이 커질수록 내부 압력과 외부 압력의 차이가 커지는 것으로 바꾼다."
          }
        },
        {
          "number": 4,
          "truth": "TRUE",
          "basis": [
            "그런데 지질과 단백질로 구성된 계면 활성제가 분비되어 액체층의 표면 장력을 낮춘다.",
            "이에 따라 폐포의 확장이 쉬워진다."
          ],
          "twist": null
        },
        {
          "number": 5,
          "truth": "TRUE",
          "basis": [
            "이때 분사된 잉크는 공기 중에서 방울의 형태가 되며 이 잉크 방울은 종이에 도달한다.",
            "라플라스 식에서 알 수 있듯이, 이때의 구형의 잉크 방울에서도 내부 압력은 외부 압력보다 높다."
          ],
          "twist": null
        }
      ]
    },
    {
      "slot": 2,
      "stemPolarity": "SELECT_CORRECT",
      "scope": "CONCEPT",
      "concept": "오네소르게 수",
      "answer": 4,
      "choices": [
        {
          "number": 1,
          "truth": "FALSE",
          "basis": [
            "오네소르게 수는 잉크의 점도가 클수록 크고, 잉크의 표면 장력, 잉크의 밀도, 노즐의 지름, 이 세 값의 곱이 클수록 작다."
          ],
          "twist": {
            "label": "점도에 따른 증감 역전",
            "targetQuote": "오네소르게 수는 잉크의 점도가 클수록 크고",
            "change": "다른 요인들이 일정할 때 잉크의 점도가 커질수록 오네소르게 수가 작아지는 것으로 바꾼다."
          }
        },
        {
          "number": 2,
          "truth": "FALSE",
          "basis": [
            "오네소르게 수는 잉크의 점도가 클수록 크고, 잉크의 표면 장력, 잉크의 밀도, 노즐의 지름, 이 세 값의 곱이 클수록 작다."
          ],
          "twist": {
            "label": "곱에 따른 증감 역전",
            "targetQuote": "잉크의 표면 장력, 잉크의 밀도, 노즐의 지름, 이 세 값의 곱이 클수록 작다.",
            "change": "잉크의 점도가 일정할 때 표면 장력과 밀도와 노즐 지름의 곱이 커질수록 오네소르게 수가 커지는 것으로 바꾼다."
          }
        },
        {
          "number": 3,
          "truth": "FALSE",
          "basis": [
            "가령 점도가 커서 오네소르게 수가 이 범위보다 크게 되면 잉크가 노즐 밖으로 나오지 못한다.",
            "이와 반대의 경우, 수많은 위성 잉크 방울이 생겨 원치 않는 오염이 발생한다."
          ],
          "twist": {
            "label": "범위 초과 시 결과 교체",
            "targetQuote": "점도가 커서 오네소르게 수가 이 범위보다 크게 되면 잉크가 노즐 밖으로 나오지 못한다.",
            "change": "점도가 커서 오네소르게 수가 안정적인 인쇄 범위보다 커질 때의 결과를 잉크의 분사 불가에서 수많은 위성 잉크 방울의 발생으로 바꾼다."
          }
        },
        {
          "number": 4,
          "truth": "TRUE",
          "basis": [
            "오네소르게 수는 잉크의 점도, 표면 장력, 밀도와 잉크젯 프린터의 노즐 지름에 의해 결정된다.",
            "오네소르게 수에 영향을 주는 네 요인에 의해 오네소르게 수가 결정되면 이로부터 안정적인 인쇄 가능 정도를 파악할 수 있다."
          ],
          "twist": null
        },
        {
          "number": 5,
          "truth": "FALSE",
          "basis": [
            "일반적으로 오네소르게 수의 범위가 대략 0.1에서 1.0 사이이면 안정적인 인쇄가 가능하다."
          ],
          "twist": {
            "label": "안정 범위의 수치 이동",
            "targetQuote": "오네소르게 수의 범위가 대략 0.1에서 1.0 사이이면",
            "change": "일반적으로 안정적인 인쇄가 가능한 오네소르게 수의 범위를 대략 0.1에서 1.0 사이에서 대략 1.0에서 10.0 사이로 바꾼다."
          }
        }
      ]
    }
  ]
}

